async def act(page):
    import re
    import asyncio

    # Helper: normalize non-breaking spaces and trim
    def normalize_nbsp(s: str) -> str:
        if s is None:
            return ""
        return s.replace('\u00A0', ' ').strip()

    # Helper: parse currency-like text into float (strip symbols, commas)
    def parse_currency(s: str) -> float:
        if s is None:
            return 0.0
        s = normalize_nbsp(s)
        if s == "":
            return 0.0
        # Remove anything except digits, dot, minus
        cleaned = re.sub(r"[^0-9.\-]", "", s)
        if cleaned == "":
            return 0.0
        try:
            return float(cleaned)
        except Exception:
            return 0.0

    # Try to select a combobox option whose visible label contains the given substring (case-insensitive)
    async def select_combobox_option_by_substr(substr: str) -> bool:
        combos = page.get_by_role("combobox")
        cnt = await combos.count()
        for i in range(cnt):
            try:
                # get option visible texts via accessibility
                opts = await combos.nth(i).get_by_role("option").all_inner_texts()
            except Exception:
                opts = []
            for opt_text in opts:
                if substr.lower() in normalize_nbsp(opt_text).lower():
                    # select by the exact visible label read from DOM
                    try:
                        await combos.nth(i).select_option(label=opt_text)
                        return True
                    except Exception:
                        # try by value fallback
                        try:
                            # read values via evaluate if available
                            # fallback: attempt substring match on option values
                            option_values = await combos.nth(i).get_by_role("option").all()
                        except Exception:
                            pass
        return False

    # Find the first table that has a "Grand Total" column and return locator + header texts
    async def find_table_with_grand_total():
        tables = page.get_by_role("table")
        tcount = await tables.count()
        for i in range(tcount):
            try:
                headers = await tables.nth(i).get_by_role("columnheader").all_inner_texts()
            except Exception:
                headers = []
            headers_norm = [normalize_nbsp(h) for h in headers]
            for h in headers_norm:
                if 'grand total' in h.lower():
                    return tables.nth(i), headers_norm
        return None, None

    # Extract up to n grand totals from the first data rows of the given table
    async def extract_top_n_grand_totals_from_table(table, headers_norm, n: int):
        if table is None:
            return []
        # find index of Grand Total header
        gt_idx = None
        for idx, h in enumerate(headers_norm):
            if 'grand total' in h.lower():
                gt_idx = idx
                break
        if gt_idx is None:
            return []
        rows = table.get_by_role('row')
        rcount = await rows.count()
        totals = []
        for ri in range(rcount):
            try:
                # get cells for this row
                cells = await rows.nth(ri).get_by_role('cell').all_inner_texts()
            except Exception:
                cells = []
            cells_norm = [normalize_nbsp(c) for c in cells]
            # skip obviously header-like rows (if any header token present in cells)
            if not cells_norm:
                continue
            if any(h.lower() in ' '.join(cells_norm).lower() for h in headers_norm):
                continue
            # If gt_idx out of range, treat as empty
            if gt_idx < len(cells_norm):
                gt_text = cells_norm[gt_idx]
            else:
                gt_text = ''
            totals.append(parse_currency(gt_text))
            if len(totals) >= n:
                break
        return totals

    # Main flow: navigate to orders grid, filter by status substrings and sum last n grand totals
    await page.goto('/index.php/admin/sales/order/')
    # Give the grid a moment to render
    await asyncio.sleep(1)

    async def get_sum_for_status_substr(status_substr: str, n: int):
        # Attempt to select a combobox option matching the status substring
        selected = await select_combobox_option_by_substr(status_substr)
        # Try to press a Search/Filter button if present to apply filters
        applied = False
        for btn_name in ['Search', 'Filter', 'Submit', 'Apply Filters']:
            try:
                btn = page.get_by_role('button', name=btn_name)
                if await btn.count() > 0:
                    await btn.first.click()
                    applied = True
                    break
            except Exception:
                pass
        # Wait briefly for results to refresh
        await asyncio.sleep(1)
        # Find a table with Grand Total
        table, headers = await find_table_with_grand_total()
        totals = await extract_top_n_grand_totals_from_table(table, headers or [], n)
        return sum(totals)

    n = 4
    cancelled_sum = await get_sum_for_status_substr('cancel', n)
    completed_sum = await get_sum_for_status_substr('complete', n)

    difference = completed_sum - cancelled_sum

    # Print and return the numeric difference
    print(difference)
    return difference

